    function loadingPanel(){return '<section class="hsu-panel" role="status"><h2>'+(error?'Chưa mở được học liệu':'Đang tải gói học phần…')+'</h2><p>'+esc(error||'Tải theo nhu cầu và kiểm tra checksum trước khi dùng.')+'</p>'+(error?btn('Thử lại','retry'):'')+'</section>';}
    function draw(){const persistence=instance.store.getPersistence?.();if(persistence?.status==='protected')return '<div class="hsw-surface hsu"><section class="hsu-panel" role="alert"><h1>Dữ liệu học cần phục hồi</h1><p>'+esc(persistence.error)+'</p><p>Bản gốc được giữ. Xuất dữ liệu phục hồi trước khi thay đổi phiên bản hoặc dùng công cụ khôi phục.</p>'+btn('Tải bản phục hồi','backup-recovery','data-hsw-recovery')+'</section></div>';if(!catalogue)return '<div class="hsw-surface hsu">'+loadingPanel()+'</div>';const value=w(),pane=value.navigation.pane||'home',drawers={home,catalogue:courseList,program,course,lesson,practice:()=>questions('practice'),diagnostic:()=>questions('diagnostic'),exam,library,progress,project,teacher};if(['course','lesson','practice','diagnostic','exam','project'].includes(pane)&&loaded?.id!==courseId()&&!loading&&!error)void ensure(courseId());return '<div class="hsw-surface hsu">'+preview()+'<nav class="hsu-nav" aria-label="Khu đại học">'+Object.entries(panes).filter(([id])=>id!=='teacher'||C.can(state().role,'assign')||C.can(state().role,'platform-admin')).map(([id,label])=>btn(label,'pane','data-u-pane="'+id+'"'+(pane===id?' aria-current="page"':''))).join('')+'</nav>'+(drawers[pane]||home)()+'</div>';}
    function applyExam(action){flush();let updated;update(value=>{const old=value.sessions[value.activeSessionId];if(!old)throw Error('Chưa có phiên kiểm tra.');updated=A.update(old,action,{gradeQuestion:C.gradeQuestion});value.sessions[old.id]=updated;if(old.status!=='submitted'&&updated.status==='submitted'){for(const q of updated.questions){const result=updated.result.items.find(r=>r.questionId===q.id),next=U.attempt(value,q,updated.answers[q.id]??'',result,updated.blueprint.subjectId,{id:updated.id+'.'+q.id,now:updated.submittedAt});Object.assign(value,next);}}},'uni:assessment');return updated;}
    async function click(event,button){const action=button.dataset.uAction;if(!action)return false;event.preventDefault();flush();if(action==='pane'){go(button.dataset.uPane);if(button.dataset.uPane==='teacher')await loadTeacher();}
      else if(action==='course')go('course',{courseId:button.dataset.uId,lessonId:''});
      else if(action==='preview'){update(value=>{value.preview=!value.preview;},'uni:preview');render();}
      else if(action==='lesson'){if(!w().preview){go('course');return true;}go('lesson',{lessonId:button.dataset.uLesson});}
      else if(action==='practice')go('practice',{lessonId:button.dataset.uLesson||''});
      else if(action==='diagnostic')go('diagnostic',{lessonId:''});
      else if(action==='read'){update(value=>{value.progress[button.dataset.uLesson]={viewedAt:new Date().toISOString(),updatedAt:new Date().toISOString(),status:'viewed'};},'uni:lesson-viewed');render();}
      else if(action==='bookmark'){const id=button.dataset.uId;update(value=>{value.bookmarks[id]={active:!value.bookmarks[id]?.active,updatedAt:new Date().toISOString()};},'uni:bookmark');render();}
      else if(action==='project')go('project');
      else if(action==='exam-intro')go('exam',{examIntro:true});
      else if(action==='continue-exam')go('exam',{examIntro:false});
      else if(action==='start-exam'){if(!w().preview)throw Error('Chọn xem trước bản biên soạn trước khi luyện.');const old=session();if(old&&old.status!=='submitted')throw Error('Hãy tiếp tục hoặc nộp phiên đang có trước khi mở phiên mới.');const s=A.createSession({ownerId:state().ownerId,learnerProfileId:state().learnerProfileId,blueprint:loaded.blueprint,questions:loaded.lessons.flatMap(l=>l.questions),mode:button.dataset.uMode,seed:String(Date.now())});update(value=>{value.sessions[s.id]=s;value.activeSessionId=s.id;value.navigation.examIntro=false;},'uni:assessment-start');render();}
      else if(action==='exam-index'){applyExam({type:'navigate',index:Number(button.dataset.uIndex)});render();}
      else if(action==='exam-flag'){applyExam({type:'flag',questionId:session().questions[session().questionIndex].id,on:!session().flagged.includes(session().questions[session().questionIndex].id)});render();}
      else if(action==='exam-pause'||action==='exam-resume'){applyExam({type:action==='exam-pause'?'pause':'resume'});render();}
      else if(action==='exam-confirm'){const dialog=bridge.dialog('<form data-u-confirm><h2>Nộp phiên kiểm tra?</h2><p>Câu chưa trả lời được ghi nhận. Bài giải thích có thể cần nhận xét.</p><button type="submit" name="choice" value="submit">Nộp bài</button><button type="submit" name="choice" value="cancel">Quay lại làm</button></form>');dialog.querySelector('[value=cancel]').focus();}
      else if(action==='review')go('lesson',{courseId:button.dataset.uId,lessonId:button.dataset.uLesson});
      else if(action==='program-page'){page=Number(button.dataset.uPage);render();}
      else if(action==='library-page'){libraryPage=Number(button.dataset.uPage);render();}
      else if(action==='flash'){const c=await D.loadCourse(button.dataset.uId);if(disposed)return true;const q=c.lessons.flatMap(l=>l.questions).find(q=>q.id===button.dataset.uQuestion);if(q)bridge.dialog('<h2>'+esc(q.prompt)+'</h2><details><summary>Lật thẻ / xem giải thích</summary><p>'+esc(q.explanation)+'</p></details><p>Xem thẻ không tự xác nhận đã nhớ.</p><form method="dialog"><button type="submit">Đóng</button></form>');}
      else if(action==='backup-recovery')bridge.download('hh-school-recovery.json',JSON.stringify(instance.store.getRecoveryData(),null,2),'application/json');
      else if(action==='backup')bridge.download('hh-school-backup.json',instance.store.export(),'application/json');
      else if(action==='teacher-refresh')await loadTeacher();
      else if(action==='retry'){error='';if(!catalogue)void boot();else{loaded=null;void ensure(courseId());}render();}
      else if(action==='bridge'){const grade=Number(button.dataset.uGrade),lessonId=button.dataset.uId;instance.store.update(s=>{if(s.profile.managed&&s.role==='student'&&s.profile.grade!==grade)throw Error('Hồ sơ được quản lý chưa được phép đổi lớp; hãy mở bài trong lớp được giao.');s.profile.grade=grade;s.activeSubjectId='math';s.activeLessonId=lessonId;return s;},'uni:bridge-open');root.location.hash='#/learn/lesson';}
      return true;
    }
    function capture(target){if(target.matches('[data-u-note]')){const id=target.dataset.uNote,prior=pending.get('notes|'+id)||w().notes[id]||{};stage('notes',id,{...prior,text:target.value});return true;}if(target.matches('[data-u-resource-anchor]')){const id=target.dataset.uResourceAnchor,prior=pending.get('notes|'+id)||w().notes[id]||{};stage('notes',id,{...prior,anchor:target.value});return true;}
      const form=target.closest('form');if(!form)return false;if(form.dataset.uGrade){const f=new FormData(form);stage('drafts','teacher-grade:'+form.dataset.uGrade,{score:String(f.get('score')||''),feedback:String(f.get('feedback')||''),redo:f.get('redo')==='on',answerRevision:Number(form.dataset.uRevision),submitted:false});return true;}
      if(form.dataset.uQuestion){stage('drafts',form.dataset.uQuestion,{value:new FormData(form).get('answer')||'',submitted:false});return true;}
      if(form.dataset.uProject){const prior=w().projects[form.dataset.uProject]||{},f=new FormData(form);stage('projects',form.dataset.uProject,{...prior,answer:String(f.get('answer')||''),assignmentId:String(f.get('assignmentId')||''),status:'draft-device'});return true;}
      if(form.dataset.uLab){stage('labs',form.dataset.uLab,{...w().labs[form.dataset.uLab],values:Object.fromEntries(new FormData(form))});return true;}
      if(form.dataset.uExam){const s=session();if(s?.status!=='active')return true;const value=String(new FormData(form).get('answer')||''),now=Date.now();root.clearTimeout(timer);pending.set('exam|'+form.dataset.uExam,{value,now,sessionId:s.id});timer=root.setTimeout(flushAll,250);return true;}
      return false;
    }
    const flushDrafts=flush;
    function flushAll(){const examRows=[...pending].filter(([key])=>key.startsWith('exam|'));for(const [key]of examRows)pending.delete(key);flushDrafts();if(examRows.length)update(value=>{for(const [key,row]of examRows){const old=value.sessions[row.sessionId];if(old?.status==='active')value.sessions[row.sessionId]=A.update(old,{type:'answer',questionId:key.slice(5),value:row.value},{now:row.now,gradeQuestion:C.gradeQuestion});}},'uni:exam-autosave');}
    function input(event){if(event.target.matches('[data-school-search]')){query=event.target.value;page=0;libraryPage=0;root.clearTimeout(searchTimer);searchTimer=root.setTimeout(()=>{if(!['catalogue','library'].includes(nav().pane))update(value=>{value.navigation.pane='catalogue';},'uni:search');render();},250);return true;}return capture(event.target);}
    function change(event){if(event.target.dataset.uContext){flushAll();const key=event.target.dataset.uContext,value=event.target.value;update(u=>{u.context[key]=key==='year'?Number(value):value;if(key==='institutionId'){const program=catalogue.programs.find(p=>p.institutionId===value);u.context.programId=program?.id||'self-study';u.context.cohort=program?.cohort||'';}if(key==='programId')u.context.cohort=catalogue.programs.find(p=>p.id===value)?.cohort||'';u.context.updatedAt=new Date().toISOString();},'uni:context');page=0;render();return true;}if(event.target.hasAttribute('data-u-class-select')){void loadTeacher(event.target.value).catch(e=>bridge.toast(e.message));return true;}return capture(event.target);}
    async function submit(event){const form=event.target;if(![...form.attributes].some(a=>a.name.startsWith('data-u-')))return false;event.preventDefault();flushAll();const serverForm=form.matches('[data-u-class],[data-u-assign],[data-u-grade],[data-u-join]');if(serverForm&&form.dataset.busy==='true')return true;const serverButton=serverForm?form.querySelector('button[type=submit]'):null;if(serverForm){form.dataset.busy='true';if(serverButton)serverButton.disabled=true;}try{
      if(form.hasAttribute('data-u-search')||form.hasAttribute('data-u-program-search')){const f=new FormData(form);query=String(f.get('query')||'');field=String(f.get('field')||field);page=0;libraryPage=0;render();return true;}
      if(form.dataset.uQuestion){if(!w().preview)throw Error('Chọn xem trước trước khi làm bài.');const q=[...loaded.diagnostic,...loaded.lessons.flatMap(l=>l.questions)].find(q=>q.id===form.dataset.uQuestion),value=String(new FormData(form).get('answer')||'');if(!value.trim())throw Error('Hãy nhập câu trả lời.');const result=C.gradeQuestion(q,value);instance.store.update(s=>{s.universityWorkspace=U.attempt(s.universityWorkspace,q,value,result,loaded.id);return s;},'uni:attempt');feedback.set(q.id,result);render();return true;}
      if(form.dataset.uLab){const values=Object.fromEntries(new FormData(form));calculate(form.dataset.uLab,values);update(u=>{u.labs[form.dataset.uLab]={values,resultValues:values,calculated:true,updatedAt:new Date().toISOString()};},'uni:lab');render();return true;}
      if(form.dataset.uExam){applyExam({type:'answer',questionId:form.dataset.uExam,value:String(new FormData(form).get('answer')||'')});form.querySelector('output').textContent='Đã ghi câu trả lời; kiểm tra trạng thái lưu trên thiết bị.';return true;}
      if(form.hasAttribute('data-u-confirm')){if(event.submitter?.value==='submit'){applyExam({type:'submit'});form.closest('dialog').close();render();}else form.closest('dialog').close();return true;}
      if(form.hasAttribute('data-u-plan')){const f=new FormData(form),id=String(f.get('courseId')),c=await D.loadCourse(id),minutes=Number(f.get('minutes')),date=String(f.get('date'));if(minutes<10||minutes>180||!Number.isFinite(minutes))throw Error('Chọn 10–180 phút dự kiến mỗi ngày.');const items=U.planDates(c.lessons.map(l=>l.id),date);update(u=>{u.plans[id]={deadline:date,minutes,items,updatedAt:new Date().toISOString()};},'uni:plan');render();return true;}
      if(form.dataset.uProject){const f=new FormData(form),answer=String(f.get('answer')||''),assignmentId=String(f.get('assignmentId')||''),id=form.dataset.uProject;if(!answer.trim())throw Error('Nhập bài làm trước khi lưu phiên bản.');if(form.dataset.busy==='true')return true;form.dataset.busy='true';try{const revisionId='project-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7);update(u=>{const prior=u.projects[id]||{};u.projects[id]={...prior,answer,assignmentId,status:'submitted-local',updatedAt:new Date().toISOString(),revisions:{...prior.revisions,[revisionId]:{answer,at:new Date().toISOString()}}};},'uni:project-version');if(assignmentId){if(!state().assignments.some(a=>String(a.id||a._id)===assignmentId&&a.lessonIds?.includes(id+'.project')))throw Error('Bài giao chưa thuộc chuỗi này.');const previous=state().submissions.find(s=>String(s.assignmentId)===assignmentId),response=await instance.sync.submitAssignment({assignmentId,learnerProfileId:state().learnerProfileId,answer,expectedRevision:Number(previous?.answerRevision||0)});if(disposed)return true;update((u,s)=>{u.projects[id].status='submitted-server';s.submissions=s.submissions.filter(x=>String(x.assignmentId)!==assignmentId).concat({assignmentId,answer,status:response.status,answerRevision:response.answerRevision,id:response.submissionId});},'uni:project-submitted');}render();}finally{form.dataset.busy='false';}return true;}
      if(form.hasAttribute('data-u-join')){await instance.sync.joinClass(String(new FormData(form).get('inviteCode')),state().learnerProfileId);const [a,b]=await Promise.all([instance.sync.assignments(state().learnerProfileId),instance.sync.submissions('learnerProfileId='+encodeURIComponent(state().learnerProfileId))]);if(disposed)return true;instance.store.update(s=>{s.assignments=(a.items||[]).map(x=>({...x,id:String(x.id||x._id)}));s.submissions=(b.items||[]).map(x=>({...x,id:String(x.id||x._id),assignmentId:String(x.assignmentId)}));return s;},'uni:class-joined');bridge.toast('Đã tham gia lớp và tải bài giao.');render();return true;}
      if(form.hasAttribute('data-u-class')){const f=new FormData(form),r=await instance.sync.createClass({name:String(f.get('name')),educationLevel:'university',program:String(f.get('program'))});if(disposed)return true;bridge.dialog('<h2>Mã mời lớp mới</h2><p>Chỉ chia sẻ với thành viên dự định tham gia.</p><code>'+esc(r.item.inviteCode)+'</code><form method="dialog"><button type="submit">Đóng</button></form>');await loadTeacher(r.item.id);return true;}
      if(form.hasAttribute('data-u-assign')){const f=new FormData(form),id=String(f.get('courseId')),dueAt=new Date(String(f.get('dueAt')));if(!classId||!Number.isFinite(dueAt.getTime()))throw Error('Chọn lớp và hạn nộp hợp lệ.');await instance.sync.createAssignment({classId,title:String(f.get('title')),dueAt:dueAt.toISOString(),lessonIds:[id+'.project'],lockAnswers:false});await loadTeacher();return true;}
      if(form.dataset.uGrade){const f=new FormData(form);await instance.sync.gradeSubmission({submissionId:form.dataset.uGrade,answerRevision:Number(form.dataset.uRevision),score:Number(f.get('score')),feedback:String(f.get('feedback')),requireRedo:f.get('redo')==='on'});if(disposed)return true;update(u=>{u.drafts['teacher-grade:'+form.dataset.uGrade]={submitted:true,value:null,updatedAt:new Date().toISOString()};},'uni:grade-saved');await loadTeacher();return true;}
      return true;
      }finally{if(serverForm){form.dataset.busy='false';if(serverButton?.isConnected)serverButton.disabled=false;}}
    }
    clock=root.setInterval(()=>{if(disposed)return;const s=session();if(!s||s.status!=='active')return;const el=instance.host.querySelector('[data-u-clock]'),seconds=Math.ceil(A.remainingMs(s)/1000);if(el)el.textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');if(s.mode==='mock'&&seconds<=0)try{flushAll();applyExam({type:'tick'});render();}catch(e){bridge.toast(e.message);}},1000);
